import type { SupabaseClient } from '@supabase/supabase-js';
import type { RedisClient } from './redis';
import type { Env } from '../types';
import { captureError } from '../lib/sentryHelper';
import { notify } from './agentEvents';

// ─── Reputation Tiers ────────────────────────────────────

export interface ReputationTier {
  level: string;
  min_rep: number;
  next_unlock: string | null;
  next_unlock_rep: number | null;
}

const TIERS = [
  { level: 'elder', min: 300, next_unlock: null, next_unlock_rep: null },
  { level: 'veteran', min: 100, next_unlock: 'Elder — mentor role, chain quests, featured in city_bulletin', next_unlock_rep: 300 },
  { level: 'established', min: 25, next_unlock: 'Veteran — event quests, higher service prices, premium actions', next_unlock_rep: 100 },
  { level: 'newcomer', min: 0, next_unlock: 'Established — create quests, list marketplace services', next_unlock_rep: 25 },
] as const;

export function getReputationLevel(rep: number): ReputationTier {
  for (const tier of TIERS) {
    if (rep >= tier.min) {
      return {
        level: tier.level,
        min_rep: tier.min,
        next_unlock: tier.next_unlock,
        next_unlock_rep: tier.next_unlock_rep,
      };
    }
  }
  const fallback = TIERS[TIERS.length - 1];
  return { level: fallback.level, min_rep: fallback.min, next_unlock: fallback.next_unlock, next_unlock_rep: fallback.next_unlock_rep };
}

// ─── Get Reputation (cached) ─────────────────────────────

/**
 * Fetch a bot's total reputation, cached in Redis for 60s.
 */
export async function getReputation(
  supabase: SupabaseClient,
  redis: RedisClient,
  botId: string,
): Promise<number> {
  const cacheKey = `rep:${botId}`;

  try {
    const cached = await redis.get(cacheKey);
    if (cached !== null) return parseInt(cached, 10);
  } catch { /* cache miss — query DB */ }

  const { data } = await supabase
    .from('v_bot_reputation_stats')
    .select('reputation')
    .eq('bot_id', botId)
    .maybeSingle();

  const rep = data?.reputation ?? 0;

  try { await redis.set(cacheKey, String(rep), 60); } catch { /* non-fatal */ }

  return rep;
}

// ─── Reputation Gate Check ───────────────────────────────

const EARN_HINTS: Record<string, string> = {
  '25': 'Complete quests, collaborate with other bots, and submit artifacts to earn reputation.',
  '100': 'Keep creating, completing quests, and collaborating to build your reputation.',
  '300': 'Continue creating exceptional work and mentoring others to reach Elder status.',
};

/**
 * Check if a bot meets a reputation requirement.
 * Returns null if OK, or a 403 Response if blocked.
 * NPCs always pass (is_npc check).
 */
export async function checkReputationGate(
  supabase: SupabaseClient,
  redis: RedisClient,
  botId: string,
  requiredRep: number,
  action: string,
): Promise<Response | null> {
  // NPCs bypass reputation gates
  const { data: bot } = await supabase
    .from('bots')
    .select('is_npc')
    .eq('id', botId)
    .single();

  if (bot?.is_npc) return null;

  const rep = await getReputation(supabase, redis, botId);

  if (rep >= requiredRep) return null;

  const hint = EARN_HINTS[String(requiredRep)] || EARN_HINTS['25'];

  return new Response(JSON.stringify({
    success: false,
    error: `Reputation ${rep} is below ${requiredRep} required to ${action}. ${hint}`,
    current_reputation: rep,
    required_reputation: requiredRep,
  }), { status: 403, headers: { 'Content-Type': 'application/json' } });
}

export type ReputationType =
  | 'quest_completion'
  | 'reaction_received'
  | 'human_reaction_received'
  | 'collaboration'
  | 'peer_review'
  | 'admin_grant'
  | 'decay'
  | 'challenge_given'
  | 'challenge_received'
  | 'endorsement_received'
  | 'report_received'
  | 'report_slashed'
  | 'mentorship_completed'
  | 'competition_entry'
  | 'competition_podium'
  | 'competition_win'
  // K0-6 (#646) — Coliseum Kombat (no DB CHECK on reputation_events.type)
  | 'kombat_entry'
  | 'kombat_win'
  // #749 — The Kernel Gauntlet (capability-CTF); no DB CHECK on the column
  | 'ctf_entry'
  | 'ctf_win'
  // RACE-2 (#1081) — Racing 3D ladder (no DB CHECK on reputation_events.type)
  | 'racing_entry'
  | 'racing_win'
  // SKI-2 (#1139) — Ski Cross ladder (no DB CHECK on reputation_events.type)
  | 'ski_entry'
  | 'ski_win'
  // Civic engagement wave (1 Aug 2026) — governance participation earns rep.
  // Each awards once per proposal per agent via idx_reputation_events_dedupe
  // (bot_id, type, reference_id); no CHECK on the column.
  | 'civic_vote'
  | 'civic_comment'
  | 'civic_pledge';

/**
 * F6: Detect tier crossings caused by a reputation award and fire an
 * inbox + channel notification when the bot crosses 25 / 100 / 300.
 *
 * Reads previous reputation from the 60s-cached helper, so the hot path
 * costs zero DB queries on cache hit. On tier change, invalidates the
 * cache (so the next read sees the new total) and fires `notify()` —
 * which is itself fire-and-forget and never rejects.
 *
 * Idempotent: dedupe_key `tier:${botId}:${newLevel}` collapses concurrent
 * crossings into a single inbox row via idx_inbox_dedupe (partial unique).
 *
 * Negative or zero amounts (decay, refunds) are filtered upstream — this
 * function will never advance a tier on amount <= 0.
 */
export async function notifyOnTierCrossing(
  supabase: SupabaseClient,
  redis: RedisClient,
  env: Env,
  botId: string,
  amount: number,
): Promise<void> {
  if (amount <= 0) return;

  const prev = await getReputation(supabase, redis, botId);
  const next = prev + amount;
  const prevTier = getReputationLevel(prev);
  const nextTier = getReputationLevel(next);
  if (prevTier.level === nextTier.level) return;

  // Invalidate the 60s cache so subsequent reads in this request reflect
  // the new total. Best-effort — if Redis is down, the cache simply
  // expires naturally within 60s.
  try { await redis.delete(`rep:${botId}`); } catch { /* non-fatal */ }

  await notify(supabase, env, botId, 'reputation_tier_advance', {
    previous_tier: prevTier.level,
    new_tier: nextTier.level,
    new_total: next,
    crossed_threshold: nextTier.min_rep,
    next_unlock: nextTier.next_unlock,
    next_unlock_rep: nextTier.next_unlock_rep,
  }, { dedupeKey: `tier:${botId}:${nextTier.level}` });
}

/**
 * Grant reputation to a bot. Uses dedupe index to prevent double-granting.
 * Fire-and-forget safe — call with .catch(() => {}).
 *
 * F6: pass `notifyOpts: { redis, env }` to fire a `reputation_tier_advance`
 * inbox event when the award causes the bot to cross 25 / 100 / 300.
 * When omitted, behaviour is unchanged from pre-F6 (no notification).
 */
export async function grantReputation(
  supabase: SupabaseClient,
  botId: string,
  amount: number,
  type: ReputationType,
  referenceId: string | null,
  referenceType: string | null,
  description?: string,
  notifyOpts?: { redis: RedisClient; env: Env },
): Promise<boolean> {
  const { error } = await supabase
    .from('reputation_events')
    .insert({
      bot_id: botId,
      amount,
      type,
      reference_id: referenceId,
      reference_type: referenceType,
      description: description || null,
    });

  if (error) {
    if (error.code === '23505') return false; // dedupe hit
    captureError('Reputation grant error', error);
    return false;
  }

  // F6: fire tier-crossing notification on successful, non-deduped award
  // with positive amount. Fire-and-forget — does not extend caller-observable
  // latency on the rare tier-change path. notify() is itself defensive.
  if (notifyOpts && amount > 0) {
    notifyOnTierCrossing(supabase, notifyOpts.redis, notifyOpts.env, botId, amount)
      .catch(() => { /* belt-and-braces; notify swallows internally */ });
  }

  return true;
}

