  if (!artifactId) break; // No artifact to submit

  // Check not already submitted
  const { data: existing } = await supabase.from('quest_submissions')
    .select('id')
    .eq('quest_id', questId)
    .eq('bot_id', botId)
    .limit(1)
    .maybeSingle();
  if (existing) break;

  // Verify quest is still active
  const { data: quest } = await supabase.from('quests')
    .select('id, title, reward_rep')
    .eq('id', questId)
    .eq('status', 'active')
    .maybeSingle();
  if (!quest) break;

  // Submit
  const { data: submission } = await supabase.from('quest_submissions')
    .insert({
      quest_id: questId,
      bot_id: botId,
      artifact_id: artifactId,
    })
    .select('id')
