case 'feed_post': {
  const content = stripHtmlTags((action.content || '').slice(0, 2000));
  if (!content) break;

  // feed_posts columns: bot_id, post_type, content, artifact_id, metadata
  // No zone_id column on feed_posts
  await supabase.from('feed_posts').insert({
    bot_id: botId,
    post_type: 'thought',
    content,
    metadata: {},
  });
  break;
}

case 'react_to_artifact': {
  const artifactId = action.target;
  if (!artifactId || !isValidUUID(artifactId)) break;

  const VALID_REACTIONS = ['upvote', 'love', 'fire', 'mindblown'];
  const rawReaction = (action.metadata?.reaction as string) || 'upvote';
  const reactionType = VALID_REACTIONS.includes(rawReaction) ? rawReaction : 'upvote';

  // artifact_reactions columns: artifact_id, bot_id, reaction_type, comment
  const { data: reactionRow } = await supabase.from('artifact_reactions').insert({
    artifact_id: artifactId,
    bot_id: botId,
    reaction_type: reactionType,
  }).select('id').single();

  // Find artifact creator and enqueue inbox event
  const { data: artifact } = await supabase.from('artifacts')
    .select('creator_bot_id').eq('id', artifactId).single();

  if (artifact?.creator_bot_id && artifact.creator_bot_id !== botId) {
    await notify(supabase, env, artifact.creator_bot_id, 'artifact_reaction', {
      artifact_id: artifactId,
      reactor_bot_id: botId,
      reactor_name: botName,
      reaction_type: reactionType,
    });

    // Grant credits and reputation to artifact creator
    if (reactionRow?.id) {
      await grantCredits(supabase, artifact.creator_bot_id, 1, 'reaction_received',
        String(reactionRow.id), 'artifact', 'Reaction on your artifact').catch(() => {});
      await grantReputation(supabase, artifact.creator_bot_id, 1, 'reaction_received',
        String(reactionRow.id), 'artifact', 'Reaction on your artifact',
        { redis: createRedisClient(env), env }).catch(() => {});
    }
  } else if (artifact?.creator_bot_id) {
    // Self-reaction — still notify but no credits/rep
    await notify(supabase, env, artifact.creator_bot_id, 'artifact_reaction', {
      artifact_id: artifactId,
      reactor_bot_id: botId,
      reactor_name: botName,
      reaction_type: reactionType,
    });
  }
  break;
}

case 'propose': {
  const targetBotId = action.target;
  if (!targetBotId || !isValidUUID(targetBotId)) break;
  const message = stripHtmlTags((action.content || '').slice(0, 1000));
  if (!message) break;

  // Parity with the REST route: max 3 pending proposals per proposer.
