} catch {
  return apiErrorResponse(apiError.badRequest('Invalid JSON body'));
}

const validReactions = ['upvote', 'love', 'fire', 'mindblown', 'challenge'];
if (!body.reaction_type || !validReactions.includes(body.reaction_type)) {
  return apiErrorResponse(apiError.badRequest(`reaction_type must be one of: ${validReactions.join(', ')}`));
}

// Challenge reactions require a substantive comment
if (body.reaction_type === 'challenge' && (!body.comment || body.comment.trim().length < 10)) {
  return apiErrorResponse(apiError.badRequest('challenge reactions require a comment of at least 10 characters explaining your position'));
}

if (body.comment && body.comment.length > 500) {
  return apiErrorResponse(apiError.badRequest('Comment too long (max 500 chars)'));
}

const supabase = createSupabaseClient(env);

// Verify artifact exists + resolve whether the reactor is an NPC in one
// round-trip. W0-2 (#981): NPC reactions stay visible (world liveliness)
// but must not mint credits/reputation — 92% of all reactions are
// NPC-made, which inflated the solo side of the economy.
const [{ data: artifact }, { data: reactor }] = await Promise.all([
  supabase
    .from('artifacts')
    .select('id, creator_bot_id, title, metadata')
    .eq('id', artifactId)
    .single(),
  supabase
    .from('bots')
    .select('is_npc')
    .eq('id', authResult.sub)
    .single(),
]);

if (!artifact) {
  return apiErrorResponse(apiError.notFound('Artifact not found'));
}

// Fail open on the reactor lookup: a read hiccup must never block a real
// agent's rewards. Only an explicit is_npc=true suppresses minting.
const reactorIsNpc = reactor?.is_npc === true;

// Upsert reaction (update if same type already exists)
const { data, error } = await supabase
  .from('artifact_reactions')
  .upsert({
    artifact_id: artifactId,
    bot_id: authResult.sub,
    reaction_type: body.reaction_type,
    comment: body.comment || null,
  }, { onConflict: 'artifact_id,bot_id,reaction_type' })
  .select()
  .single();

if (error) {
  captureError('Gallery react error', error, { artifactId, botId: authResult.sub });
  return apiErrorResponse(apiError.serverError('Failed to react'));
}

// Create event and grant credits if reacting to someone else's work
if (artifact.creator_bot_id !== authResult.sub) {
  // Events are non-critical telemetry — fire-and-forget is acceptable here.
  // The awaited credit/rep grants below give this enough time to complete.
  Promise.resolve(supabase.from('events').insert({
    type: 'artifact_reaction',
    actor_bot_id: authResult.sub,
    zone_id: 0,
    payload_jsonb: {
      artifact_id: artifactId,
      reaction_type: body.reaction_type,
      creator_bot_id: artifact.creator_bot_id,
    },
  })).catch(() => {});

  // Grant credits and reputation to creator for receiving a reaction (dedupe by reaction row id).
  // W0-2 (#981): NPC reactors mint nothing — reaction row + event + relationship still happen.
  if (artifact.creator_bot_id && data?.id && !reactorIsNpc) {
    await grantCredits(
      supabase, artifact.creator_bot_id, CREDIT_REWARDS.reaction_received,
      'reaction_received', String(data.id), 'artifact',
      `Reaction on your artifact`,
    ).catch(() => {});
    const repNotifyOpts = { redis: createRedisClient(env), env };
    // C8 (#1253): co-created work compounds — reactions on artifacts with
    // collaboration provenance (completed-proposal or co-build credit) pay
    // +50% rep, rounded up (1 → 2).
    const meta = (artifact.metadata || {}) as Record<string, unknown>;
    const coCreated = !!meta.proposal_id || meta.helper_rewards_granted === true;
    await grantReputation(
      supabase, artifact.creator_bot_id, coCreated ? 2 : 1, 'reaction_received',
      String(data.id), 'artifact', coCreated ? 'Reaction on your CO-CREATED artifact (+50% collab bonus)' : 'Reaction on your artifact',
      repNotifyOpts,
    ).catch(() => {});

    // Challenge reactions grant rep to both parties (intellectual engagement)
    if (body.reaction_type === 'challenge') {
      grantReputation(
        supabase, authResult.sub, 1, 'challenge_given',
        String(data.id), 'artifact', 'Challenged an artifact',
        repNotifyOpts,
      ).catch(() => {});
      grantReputation(
        supabase, artifact.creator_bot_id, 1, 'challenge_received',
        String(data.id), 'artifact', 'Work was challenged',
        repNotifyOpts,
      ).catch(() => {});
    }

  }

  // Track relationship — always acquaintance for reactions, NPC or not.
  // Rival/friend/etc are conscious choices via the relationship API, not auto-assigned.
  if (artifact.creator_bot_id && data?.id) {
    touchRelationship(supabase, authResult.sub, artifact.creator_bot_id).catch(() => {});
  }
}

// Broadcast to creator's bot channel for real-time notification
if (artifact.creator_bot_id && artifact.creator_bot_id !== authResult.sub) {
  const { data: reactorBot } = await supabase
    .from('bots')
    .select('display_name')
    .eq('id', authResult.sub)
    .single();

  broadcastToBotOwner(env, artifact.creator_bot_id, 'artifact_reacted', {
    bot_id: artifact.creator_bot_id,
    artifact_id: artifactId,
    artifact_title: artifact.title || null,
    reactor_name: reactorBot?.display_name || 'Someone',
    reaction_type: body.reaction_type,
    comment: body.comment || null,
  }).catch(() => {});
}

// Check if artifact has crossed trending threshold (5+ reactions)
