import type { SupabaseClient } from '@supabase/supabase-js';
import type { Env } from '../types';
import type { SwarmMemory, SwarmDecision, SwarmAction, SwarmAgentRow, SwarmPersona } from './types';
import { buildSwarmSystemPrompt, buildSwarmUserPrompt, buildSwarmEventPrompt } from './prompts';
import { swarmChatCompletion } from './llm';
import { executeAction, type ActionCycleContext } from './actions';
import { updateMemoryAfterCycle } from './memory';
import { HEARTBEAT_MAX_TOKENS, EVENT_MAX_TOKENS } from './config';
import { broadcastToChannel } from '../lib/broadcast';
import { buildCityBulletin } from '../routes/heartbeat';
import { HILLVALE_ZONE_ID } from '../lib/hillvale/names';
import { shouldOfferHillvaleVisit, shouldNudgeReturnFromHillvale } from '../lib/hillvale/visits';

/**
 * Core agent loop: perceive → reason → act → reflect.
 *
 * Two triggers:
 * - 'heartbeat': queries DB directly for city state (no self-fetch)
 * - 'event': reacts to a specific inbox event (lower token budget)
 */
export async function perceiveAndDecide(
  agent: SwarmAgentRow,
  env: Env,
  supabase: SupabaseClient,
  trigger: 'heartbeat' | 'event',
  eventContext?: { type: string; payload: Record<string, unknown> },
): Promise<{ decision: SwarmDecision; updatedMemory: SwarmMemory }> {
  const { bot_id: botId, persona, memory } = agent;

  // ── Perceive ──
  let heartbeatData: Record<string, unknown> = {};
  const effectiveZone = memory.location.zone_id ?? persona.home_zone_id;

  if (trigger === 'heartbeat') {
    heartbeatData = await gatherPerception(supabase, botId, memory, effectiveZone);
  }

  // Update last_seen_at for this bot
  await supabase.from('bots').update({
    last_seen_at: new Date().toISOString(),
    status: 'dormant',
  }).eq('id', botId);

  // Ensure bot has a position — create on first heartbeat so bots trickle in gradually
  if (trigger === 'heartbeat') {
    const { data: pos } = await supabase.from('bot_positions')
      .select('x, y')
      .eq('bot_id', botId)
      .eq('zone_id', effectiveZone)
      .maybeSingle();

    if (!pos) {
      // First time this bot appears — create position + broadcast bot_entered
      const x = Math.floor(Math.random() * 800) + 100;
      const y = Math.floor(Math.random() * 600) + 100;
      await supabase.from('bot_positions').upsert({
        bot_id: botId,
        zone_id: effectiveZone,
        x, y,
        last_updated: new Date().toISOString(),
      }, { onConflict: 'bot_id,zone_id' });
      await supabase.from('bots').update({ current_zone_id: effectiveZone, x, y }).eq('id', botId);

      broadcastToChannel(env, `zone:${effectiveZone}`, 'bot_entered', {
        bot_id: botId,
        bot_name: persona.name,
        character_type: persona.character_type || null,
        position: { x, y },
        status: 'dormant',
      }).catch(() => {});
    }
    // Existing bots with positions are already visible via getZoneBots() page load query
  }

  // ── Reason ──
  const systemPrompt = buildSwarmSystemPrompt(persona);
  const userPrompt = trigger === 'event' && eventContext
    ? buildSwarmEventPrompt(eventContext.type, eventContext.payload, memory)
    : buildSwarmUserPrompt(heartbeatData, memory, persona);

