case 'react_to_artifact': {
  if (!decision.artifact_id) break;

  const validReactions = ['upvote', 'love', 'fire', 'mindblown'];
  const reactionType = validReactions.includes(decision.reaction_type || '')
    ? decision.reaction_type!
    : validReactions[Math.floor(Math.random() * validReactions.length)];

  // Verify artifact exists
  const { data: targetArtifact } = await supabase
    .from('artifacts')
    .select('id, creator_bot_id, title')
    .eq('id', decision.artifact_id)
    .single();

  if (!targetArtifact) break;

  // Don't react to own artifacts
  if (targetArtifact.creator_bot_id === npc.id) break;

  // Save for richer memory storage after switch
  lastReactedArtifact = targetArtifact;
  lastReactionType = reactionType;

  // Upsert reaction
  const { error: reactError } = await supabase
    .from('artifact_reactions')
    .upsert({
      artifact_id: decision.artifact_id,
      bot_id: npc.id,
      reaction_type: reactionType,
      comment: decision.content?.slice(0, 500) || null,
    }, { onConflict: 'artifact_id,bot_id,reaction_type' });

  if (reactError) {
    captureError(`[npcBrain] React error for ${npc.display_name}`, new Error(reactError.message), { npcId: npc.id });
    break;
  }

  // Create event
  await supabase.from('events').insert({
    type: 'artifact_reaction',
    actor_bot_id: npc.id,
    zone_id: zoneId,
    payload_jsonb: {
      artifact_id: decision.artifact_id,
      reaction_type: reactionType,
      creator_bot_id: targetArtifact.creator_bot_id,
    },
  });

  // Broadcast to creator's bot channel
  broadcastToBotOwner(env, targetArtifact.creator_bot_id, 'artifact_reacted', {
    bot_id: targetArtifact.creator_bot_id,
    artifact_id: decision.artifact_id,
    artifact_title: targetArtifact.title || null,
    reactor_name: npc.display_name,
    reaction_type: reactionType,
    comment: decision.content || null,
  }).catch(() => {});

  // Announce in chat
  const reactMsg = decision.content
    ? `[reacted ${reactionType} to "${targetArtifact.title}": ${decision.content.slice(0, 100)}]`
    : `[reacted ${reactionType} to "${targetArtifact.title}"]`;

  const { data: reactMsgRow } = await supabase.from('chat_messages').insert({
    bot_id: npc.id,
    session_id: chatSessionId,
    message: reactMsg,
    ts: now,
  }).select('id').single();

  broadcastToChannel(env, broadcastChannel, 'bot_spoke', {
    bot_id: npc.id,
    bot_name: npc.display_name,
    content: reactMsg,
    zone_id: zoneId,
    message_id: reactMsgRow?.id,
  }).catch(() => {});

  console.log(`[npcBrain] ${npc.display_name} reacted ${reactionType} to "${targetArtifact.title}"`);
  break;
}

