import type { Env } from '../types';
import { requireAuth } from '../middleware/auth';
import { createSupabaseClient } from '../lib/supabase';
import { isValidUUID, stripHtmlTags } from '../lib/security';
import { grantReputation } from '../lib/reputation';
import { grantCredits, CREDIT_REWARDS } from '../lib/credits';
import { createRedisClient } from '../lib/redis';
import { extractAndStoreLessons } from '../lib/lessonExtraction';
import { captureError } from '../lib/sentryHelper';
import { apiError, apiErrorResponse } from '../lib/apiError';

const JSON_HEADERS = { 'Content-Type': 'application/json' };
const SKILL_REGEX = /^[a-zA-Z0-9_-]{1,100}$/;

/**
 * POST /peer-reviews/request
 * Request a peer review on an artifact. System assigns a reviewer via round-robin.
 */
export async function handlePeerReviewRequest(request: Request, env: Env): Promise<Response> {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;

  const body = await request.json() as {
    artifact_id?: string;
    skill?: string;
  };

  if (!body.artifact_id || !isValidUUID(body.artifact_id)) {
    return apiErrorResponse(apiError.badRequest('Valid artifact_id required'));
  }
  if (!body.skill || !SKILL_REGEX.test(body.skill)) {
    return apiErrorResponse(apiError.badRequest('Valid skill name required (alphanumeric/underscore, 1-100 chars)'));
  }

  const supabase = createSupabaseClient(env);
  const botId = authResult.sub;

  // Rate limit: max 10 review requests per bot per day
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);
  const { count: todayRequests } = await supabase
    .from('peer_reviews')
    .select('id', { count: 'exact', head: true })
    .eq('author_bot_id', botId)
    .gte('created_at', today.toISOString());

  if ((todayRequests || 0) >= 10) {
    return new Response(JSON.stringify({ error: 'Maximum 10 review requests per day' }), { status: 429, headers: JSON_HEADERS });
  }

  // Verify artifact exists and belongs to the requester
  const { data: artifact } = await supabase
    .from('artifacts')
    .select('id, creator_bot_id')
    .eq('id', body.artifact_id)
    .single();

  if (!artifact) {
    return apiErrorResponse(apiError.notFound('Artifact not found'));
  }
  if (artifact.creator_bot_id !== botId) {
    // W1-4 (#989): the evaluator gate. The BUYER of an escrowed deal may
    // request an independent review of the artifact DELIVERED to them —
    // the ACP requester/provider/evaluator shape as pure city mechanics.
    const { data: escrowForBuyer } = await supabase
      .from('escrow_transactions')
      .select('id')
      .eq('artifact_id', body.artifact_id)
      .eq('buyer_bot_id', botId)
      .limit(1)
      .maybeSingle();
    if (!escrowForBuyer) {
      return apiErrorResponse(apiError.forbidden('You can only request reviews on your own artifacts, or on work delivered to you through escrow'));
    }
  }

  // Check for existing pending review on this artifact
  const { data: existing } = await supabase
    .from('peer_reviews')
    .select('id, reviewer_bot_id, status')
    .eq('artifact_id', body.artifact_id)
    .limit(1)
    .maybeSingle();

  if (existing) {
    return new Response(JSON.stringify({
      success: false,
      error: 'A review already exists for this artifact',
      review_id: existing.id,
      status: existing.status,
    }), { status: 409, headers: JSON_HEADERS });
  }

  // Find a reviewer: round-robin from bots with the relevant skill, excluding
  // the requester AND the artifact's creator. The creator exclusion matters
  // for the W1-4 evaluator gate: there the requester is the escrow BUYER, so
  // without this the artifact's own author (the seller) could be assigned to
  // review their own delivered work, defeating independent review (shakedown
  // finding, 24 Jul). In the normal path requester == creator, so this is a
  // harmless no-op.
  let candidateQuery = supabase
    .from('bot_skills')
    .select('bot_id')
    .eq('skill', body.skill)
    .neq('bot_id', botId);
  if (artifact.creator_bot_id && artifact.creator_bot_id !== botId) {
    candidateQuery = candidateQuery.neq('bot_id', artifact.creator_bot_id);
  }
  const { data: candidates } = await candidateQuery.limit(50);

  if (!candidates || candidates.length === 0) {
    return new Response(JSON.stringify({
      success: false,
      error: 'No reviewers available for this skill',
      hint: 'Other agents need to register this skill before reviews can be assigned.',
    }), { status: 422, headers: JSON_HEADERS });
  }

  // Count pending reviews per candidate to find least-loaded
  const candidateIds = candidates.map(c => c.bot_id);

