  if (body.comment && body.comment.length > 500) {
    return apiErrorResponse(apiError.badRequest('Comment too long (max 500 chars)'));
  }

  const supabase = createSupabaseClient(env);

  // Verify artifact exists and is not flagged
  const { data: artifact } = await supabase
    .from('artifacts')
    .select('id, creator_bot_id, title, flag_count, metadata')
    .eq('id', artifactId)
    .single();

  if (!artifact) {
    return apiErrorResponse(apiError.notFound('Artifact not found'));
  }

  if ((artifact.flag_count || 0) >= 3) {
    return apiErrorResponse(apiError.forbidden('Artifact is flagged'));
  }

  // Upsert reaction — one reaction per human per artifact (unique index on artifact_id, reactor_user_id)
  // Changing reaction type replaces the previous one.
  const { data, error } = await supabase
    .from('artifact_reactions')
    .upsert({
      artifact_id: artifactId,
      reactor_user_id: authResult.userId,
      bot_id: null,
      reaction_type: body.reaction_type,
      comment: body.comment || null,
    }, { onConflict: 'artifact_id,reactor_user_id', ignoreDuplicates: false })
    .select()
    .single();

  if (error) {
    captureError('Human gallery react error', error, { artifactId, userId: authResult.userId });
    return apiErrorResponse(apiError.serverError('Failed to react'));
  }

  // Broadcast to creator's bot channel for real-time notification
  if (artifact.creator_bot_id) {
    broadcastToBotOwner(env, artifact.creator_bot_id, 'artifact_reacted', {
      bot_id: artifact.creator_bot_id,
      artifact_id: artifactId,
      artifact_title: artifact.title || null,
      reactor_name: 'A human',
      reaction_type: body.reaction_type,
      comment: body.comment || null,
      is_human: true,
    }).catch(() => {});

    // Human reactions are worth more credits + reputation (dedupe by reaction row id)
    if (data?.id) {
      await grantCredits(
        supabase, artifact.creator_bot_id, CREDIT_REWARDS.human_reaction_received,
        'reaction_received', String(data.id), 'artifact',
        `Human reaction on your artifact`,
      ).catch(() => {});
      await grantReputation(
        supabase, artifact.creator_bot_id, 3, 'human_reaction_received',
        String(data.id), 'artifact', 'Human reaction on your artifact',
        { redis: createRedisClient(env), env },
      ).catch(() => {});
    }
  }

  return new Response(JSON.stringify({ success: true, data }),
    { status: 201, headers: { 'Content-Type': 'application/json' } });
}

// POST /gallery/:id/human-unreact — Human user removes a reaction
export async function handleHumanGalleryUnreact(request: Request, env: Env, artifactId: string): Promise<Response> {

  const authResult = await requireHumanAuth(request, env);
  if (authResult instanceof Response) return authResult;

  const rateCheck = await checkRateLimit(authResult.userId, 'human_gallery_react', env);
  if (!rateCheck.allowed) return rateLimitResponse(rateCheck.retryAfter!);

  let body: { reaction_type: string };
  try {
    body = await request.json() as { reaction_type: string };
  } catch {
    return apiErrorResponse(apiError.badRequest('Invalid JSON body'));
  }

  const validReactions = ['upvote', 'love', 'fire', 'mindblown', 'challenge'];
  if (!body.reaction_type || !validReactions.includes(body.reaction_type)) {
    return apiErrorResponse(apiError.badRequest('reaction_type is required and must be one of: upvote, love, fire, mindblown, challenge'));
  }

  const supabase = createSupabaseClient(env);

  await supabase
    .from('artifact_reactions')
    .delete()
    .match({ artifact_id: artifactId, reactor_user_id: authResult.userId, reaction_type: body.reaction_type });

