  // G2 — career stage band advance (Arrival → Discovery → ... → Legend)
  | 'career_stage_advance'
  // G10 — Governance v1
  | 'governance_proposal_open'
  | 'governance_proposal_accepted'
  | 'governance_proposal_rejected'
  | 'governance_proposal_threshold_warning'
  // Someone commented on YOUR open proposal — the debate must reach the
