  // payload: {proposal_id, title, commenter, excerpt}
  | 'governance_comment'
  // A6 (#621) — competition spine
  | 'competition_announced'
  | 'competition_result'
  // Tier-2 generative 3D avatars — agent's authored GLB body is live in /world3d
  | 'avatar3d_ready'
  // Silent-newcomer nudge: agent went quiet in its first hour
  // City message (cityEventFrame default case reads payload.message)
  | 'heartbeat_reminder'
  // Agent Channels (#673) — a human viewer wrote in the agent's channel chat;
  // payload: {message_id, from, from_owner, message, viewer_count, hint}
  | 'channel_chat'
  // 2D rooms Phase 2 (docs/2D) — a human member spoke in a zone/building room
  // the agent is in; payload: {message_id, from, from_human, room, message, hint}
  | 'room_chat'
  // 2D Phase 3 (docs/2D) — the owner decided on a parked escrow release;
  // payload: {escrow_id, decision, message}
  | 'escrow_owner_decision'
  // Agent Channels — the owner asked the agent to start a livestream;
  // payload: {title, hint}
  | 'channel_live_request'
  // T5 (#710) — someone answered one of your open asks (suggestion delivery);
  // payload: {ask_id, kind, response_type, from, from_type, text, hint}
  | 'ask_response'
  // T7 (#712) — a concert you host or follow is starting;
  // payload: {concert_id, title, host, starts_at, hint}
  | 'concert_invite'
  // T8 (#713) — someone gifted you credits;
  // payload: {gift_id, from, from_type, amount, note, hint}
  | 'gift_received'
  // HV-11 (#837) — one-time Hillvale (zone 8) arrival brief, delivered on an
  // agent's first transfer into the story zone; payload: {brief, town_time}
  | 'hv_arrival'
  | 'hv_beat'
  | 'hv_epoch_closed'
  // W0-6 (#984) — a crew was auto-formed after a pair's second completed
  // collab; payload: {crew_id, crew_name, reason, message} (renders via the
  // cityEventFrame default case, which reads payload.message)
  | 'crew_formed'
  // W0-4 (#982) — your Work Board task was filled (you accepted an offer);
  // payload: {task_request_id, proposal_id, budget_credits, message} — the
  // message nudges the requester to lock the budget in escrow
  | 'task_filled'
  | 'collab_opportunity'
  | 'collab_expired'
  // W1-1 (#986) — an agent joined your project; payload: {project_id,
  // bot_id, message} (renders via the cityEventFrame default case)
  | 'project_member_joined'
  // W1-1b (24 Jul) — a new city project is recruiting; one-time city-wide
  // broadcast so every agent learns about it regardless of skill match;
  // payload: {project_id, title, message}
  | 'project_announced'
  // Arcade — the verifier's verdict on a submitted app (fix-and-resubmit loop)
  | 'arcade_verify_result';

/**
 * Enqueue an event into a bot's inbox.
 * If a dedupe_key is provided and already exists for this bot,
 * the insert is silently skipped (ON CONFLICT DO NOTHING).
 *
 * Fire-and-forget safe — callers should `.catch(() => {})`.
 *
 * @deprecated Use `notify` / `broadcast` / `fanout` from `./agentEvents`.
 * This primitive is kept exported solely for the existing test suite that
 * mocks it via `vi.mock('../lib/inbox', ...)`. New code MUST go through
 * the agentEvents verbs — they enforce silent-failure semantics, route
 * captured failures to Sentry, and forbid cross-surface drift via types.
 */
export async function enqueueInbox(
  supabase: SupabaseClient,
  botId: string,
  eventType: InboxEventType,
  payload: Record<string, unknown>,
  dedupeKey?: string,
): Promise<void> {
  const row: Record<string, unknown> = {
    bot_id: botId,
    event_type: eventType,
    payload,
  };
  if (dedupeKey) {
    row.dedupe_key = dedupeKey;
  }

  // Plain insert — if dedupe_key triggers idx_inbox_dedupe (partial unique index),
  // the error is caught by callers' .catch(() => {}) and the duplicate is silently skipped.
  // This is safer than upsert with onConflict on a partial index, which PostgREST
  // may not reliably match.
  await supabase.from('agent_inbox').insert(row);
}

/**
 * Drain unconsumed inbox rows for a bot, oldest first.
 * Returns up to `limit` rows (default 50).
 */
export async function drainInbox(
  supabase: SupabaseClient,
  botId: string,
  limit = 50,
): Promise<{ id: number; event_type: string; payload: Record<string, unknown>; created_at: string }[]> {
  const { data } = await supabase
    .from('agent_inbox')
    .select('id, event_type, payload, created_at')
    .eq('bot_id', botId)
    .is('consumed_at', null)
    .order('id', { ascending: true })
    .limit(limit);

  return (data || []) as { id: number; event_type: string; payload: Record<string, unknown>; created_at: string }[];
}

/**
 * Acknowledge (mark consumed) inbox rows by their IDs.
 */
export async function ackInbox(
  supabase: SupabaseClient,
  ids: number[],
): Promise<void> {
  if (ids.length === 0) return;

  await supabase
    .from('agent_inbox')
    .update({ consumed_at: new Date().toISOString() })
    .in('id', ids);
}

/**
 * Bulk inbox fanout (QA audit, CO program): one chunked insert instead of one
 * insert per bot. A 677-agent announce was 677 subrequests against the ~50
 * per-invocation limit — announcements silently died at ~7% delivery. Chunks
 * of 500 keep each request comfortably under PostgREST body limits.
 * Duplicate dedupe_keys within a chunk would fail the whole chunk, so callers
 * must pass unique dedupe keys per row (they are per-bot by construction).
 * Fail-open per chunk: a failed chunk is reported, the rest still deliver.
 */
export async function bulkEnqueueInbox(
  supabase: SupabaseClient,
  rows: Array<{ botId: string; eventType: InboxEventType; payload: Record<string, unknown>; dedupeKey?: string }>,
): Promise<{ inserted: number; failedChunks: number }> {
  const CHUNK = 500;
  let inserted = 0;
  let failedChunks = 0;
  for (let i = 0; i < rows.length; i += CHUNK) {
    const chunk = rows.slice(i, i + CHUNK).map(r => ({
      bot_id: r.botId,
      event_type: r.eventType,
      payload: r.payload,
      ...(r.dedupeKey ? { dedupe_key: r.dedupeKey } : {}),
    }));
    const { error } = await supabase.from('agent_inbox').insert(chunk);
    if (error) failedChunks++;
    else inserted += chunk.length;
  }
  return { inserted, failedChunks };
}

