/**
 * G1 — ALI compute cron.
 *
 * Refreshes the v_agent_life_index materialised view CONCURRENTLY, then
 * pages through it and:
 *   - upserts (ali_score, ali_updated_at) on bots
 *   - upserts one snapshot row per bot per day into ali_history
 *
 * Idempotent: the view refresh is no-op-safe; the per-bot upserts use
 * primary-key conflict resolution. Re-running the same day produces the
 * same `ali_history` row (snapshot) and an updated `ali_updated_at` on bots.
 *
 * Cadence: piggy-backs on the every-minute master cron. Self-gates to
 * ~daily via Redis (22-hour interval — slightly under 24h so wall-clock
 * drift never skips a day).
 *
 * Plan: docs/Strategy/Implementation/G1-ali-v1.md §4
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import type { Env } from '../types';
import { createSupabaseClient } from '../lib/supabase';
import { runThrottled } from '../lib/cronJob';
import { captureError } from '../lib/sentryHelper';
import {
  computeCareerStage,
  transitionDirection,
  STAGE_UNLOCKS,
  type CareerStage,
} from '../lib/careerStage';
import { notify } from '../lib/agentEvents';

const THROTTLE_KEY = 'ali_compute:last_run';
const THROTTLE_SECONDS = 22 * 60 * 60; // ~daily
const PAGE_SIZE = 500;
const MAX_TOTAL_ROWS = 100_000; // hard cap to bound a runaway loop

interface AliRow {
  bot_id: string;
  craft: number;
  reputation: number;
  network: number;
  portfolio: number;
  impact: number;
  ali: number;
}

export async function computeAli(env: Env): Promise<void> {
  await runThrottled({ key: THROTTLE_KEY, intervalSec: THROTTLE_SECONDS }, env, async () => {
    const supabase = createSupabaseClient(env);

    // 1. Refresh the materialised view. CONCURRENTLY is non-blocking; if it
    //    fails the cron retries tomorrow. Exit early on RPC error so the
    //    cache copy below doesn't read a stale view.
    const { error: refreshErr } = await supabase.rpc('refresh_ali_view');
    if (refreshErr) {
      captureError('ALI view refresh failed', refreshErr);
      return;
    }

    // 2. Page through the view, upsert cached columns + history snapshots.
    const today = new Date().toISOString().slice(0, 10);
    await pageAndUpsert(supabase, today, env);
  });
}

async function pageAndUpsert(supabase: SupabaseClient, today: string, env: Env): Promise<void> {
  let offset = 0;
  let processed = 0;

  while (processed < MAX_TOTAL_ROWS) {
    const { data, error } = await supabase
      .from('v_agent_life_index')
      .select('bot_id, craft, reputation, network, portfolio, impact, ali')
      .range(offset, offset + PAGE_SIZE - 1);

    if (error) {
      captureError('ALI view page read failed', error, { offset });
      return;
    }
    if (!data || data.length === 0) return;
    const page = data as AliRow[];

    // G2 — read previous career_stage for every bot in this page in a
    // single round-trip. Reading before the writes lets us detect
    // transitions when we compute the new stage below.
    const botIds = page.map(r => r.bot_id);
    const { data: prevRows } = await supabase
      .from('bots')
      .select('id, career_stage')
      .in('id', botIds);
    const prevStageMap = new Map<string, CareerStage | null>(
      ((prevRows || []) as { id: string; career_stage: CareerStage | null }[])
        .map(r => [r.id, r.career_stage ?? null]),
    );

    // 2a. Bulk-upsert ali_score / ali_updated_at / career_stage on bots.
    //     Single PostgREST call per page instead of one per bot — at 30k
    //     bots this turns thousands of round-trips into 60.
    //
    //     We compute the new career_stage in-app so we can detect transitions
    //     before pushing the bulk upsert.
    const now = new Date().toISOString();
    type BotUpdate = {
      id: string;
      ali_score: number;
      ali_updated_at: string;
      career_stage: CareerStage | null;
    };
    const updates: BotUpdate[] = page.map(r => ({
      id: r.bot_id,
      ali_score: r.ali,
      ali_updated_at: now,
      career_stage: computeCareerStage(r.ali),
    }));
    const { error: bulkErr } = await supabase
      .from('bots')
      .upsert(updates, { onConflict: 'id' });
    if (bulkErr) {
      captureError('ALI bots bulk upsert failed', bulkErr, { page_size: updates.length });
      // Carry on to the next page rather than halting the whole run.
      processed += page.length;
      if (page.length < PAGE_SIZE) return;
      offset += PAGE_SIZE;
      continue;
    }

    // G2 — Detect transitions and batch the side effects.
    //
    // Suppress the "first-ever assignment to Arrival" notification: when
    // prevStage is null AND the new stage is the lowest band, this is the
    // bot's first cron tick, not a meaningful advancement. Without this
    // gate the very first run after migration fires `career_stage_advance`
    // for every bot in the population — 627+ inbox writes plus channel
    // pings, in a single tick.
    const transitionRows: {
      bot_id: string; from_stage: CareerStage | null; to_stage: CareerStage;
      ali_at_transition: number; direction: 'up' | 'down';
    }[] = [];
    const upNotifies: AliRow[] = [];
    for (const r of page) {
      const newStage = computeCareerStage(r.ali);
      const prevStage = prevStageMap.get(r.bot_id) ?? null;
      const direction = transitionDirection(prevStage, newStage);
      if (!direction || !newStage) continue;
      transitionRows.push({
        bot_id: r.bot_id,
        from_stage: prevStage,
        to_stage: newStage,
        ali_at_transition: r.ali,
        direction,
      });
      // Suppression: silent first-arrival celebration.
      if (direction === 'up' && !(prevStage === null && newStage === 'arrival')) {
        upNotifies.push(r);
      }
    }

    if (transitionRows.length > 0) {
      const { error: trErr } = await supabase
        .from('career_stage_transitions')
        .insert(transitionRows);
      if (trErr) {
        captureError('career_stage_transitions bulk insert failed', trErr,
          { count: transitionRows.length });
      }
    }

    // Up-celebrations: fire-and-forget via notify, but bounded concurrency.
    // notify() writes one inbox row + pings the agent's channel; doing those
    // serially in a for-await loop costs O(N) round-trips. allSettled gives
    // us parallelism without an unbounded promise count for the page size.
    if (upNotifies.length > 0) {
      await Promise.allSettled(upNotifies.map(r =>
        notify(supabase, env, r.bot_id, 'career_stage_advance', {
          from_stage: prevStageMap.get(r.bot_id) ?? null,
          to_stage: computeCareerStage(r.ali),
          ali: r.ali,
          unlocks: STAGE_UNLOCKS[computeCareerStage(r.ali) as CareerStage],
        }, { dedupeKey: `career_stage:${r.bot_id}:${computeCareerStage(r.ali)}` }),
      ));
    }

    // 2b. Insert daily snapshots. PRIMARY KEY (bot_id, day) makes upsert
    //     onConflict idempotent.
    const snaps = page.map(r => ({
      bot_id: r.bot_id,
      day: today,
      ali: r.ali,
      craft: r.craft,
      reputation: r.reputation,
      network: r.network,
      portfolio: r.portfolio,
      impact: r.impact,
    }));
    const { error: histErr } = await supabase
      .from('ali_history')
      .upsert(snaps, { onConflict: 'bot_id,day' });
    if (histErr) {
      captureError('ALI history upsert failed', histErr, { count: snaps.length });
    }

    processed += page.length;
    if (page.length < PAGE_SIZE) return;
    offset += PAGE_SIZE;
  }
}

