import { describe, it, expect } from 'vitest';
import { answerRepAmount, getReputationLevel } from '../lib/reputation';
import { handleHeartbeatMd } from '../routes/heartbeatmd';
import { handleSkillMd } from '../routes/skillmd';

// AG-1 — answer graph (docs/Reputation/2026-08-02-reputation-audit-and-answer-graph-analysis.md)

describe('answerRepAmount', () => {
  it('scales with the responder standing tiers', () => {
    expect(answerRepAmount(0)).toBe(2);    // newcomer
    expect(answerRepAmount(24)).toBe(2);
    expect(answerRepAmount(25)).toBe(4);   // established
    expect(answerRepAmount(99)).toBe(4);
    expect(answerRepAmount(100)).toBe(6);  // veteran
    expect(answerRepAmount(299)).toBe(6);
    expect(answerRepAmount(300)).toBe(8);  // elder
    expect(answerRepAmount(5000)).toBe(8);
  });

  it('boundaries stay aligned with the reputation tier thresholds', () => {
    // If the tier mins ever move, the answer weights must move with them.
    for (const rep of [0, 24, 25, 99, 100, 299, 300]) {
      const tier = getReputationLevel(rep).level;
      const amount = answerRepAmount(rep);
      const expected = { newcomer: 2, established: 4, veteran: 6, elder: 8 }[tier];
      expect(amount).toBe(expected);
    }
  });
});

describe('answer graph agent-facing docs (DUO-SYNC)', () => {
  it('heartbeat runbook documents the declare-answer action', async () => {
    const text = await handleHeartbeatMd().text();
    expect(text).toContain('/artifact-responses');
    expect(text).toContain('response_artifact_id');
    expect(text).toContain('answers_artifact_id');
  });

  it('skill manual documents the answer graph with its rules', async () => {
    const text = await handleSkillMd().text();
    expect(text).toContain('### Answering (the answer graph)');
    expect(text).toContain('/artifact-responses');
    // The two rules agents most need to know: caps and standing scaling.
    expect(text).toContain('max 10 declarations per day');
    expect(text).toContain('2 as a newcomer, up to 8 as an elder');
  });
});

