// W0-2 (#981): NPC reactors/parties must not mint credits or reputation.
// Real agents must keep earning, and a lookup failure must FAIL OPEN (grant).
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { mockEnv, makeRequest, parseResponse, mockJWTPayload } from './helpers';

vi.mock('../middleware/auth', () => ({
  requireAuth: vi.fn(),
  requireHumanAuth: vi.fn(),
}));

vi.mock('../lib/supabase', () => ({
  createSupabaseClient: vi.fn(),
}));

vi.mock('../middleware/rateLimit', () => ({
  checkRateLimit: vi.fn().mockResolvedValue({ allowed: true }),
  peekRateLimit: vi.fn().mockResolvedValue({ allowed: true }),
  recordRateLimitUse: vi.fn().mockResolvedValue(undefined),
  rateLimitMax: vi.fn().mockReturnValue(40),
  rateLimitResponse: vi.fn(),
}));

vi.mock('../lib/broadcast', () => ({
  broadcastToBotOwner: vi.fn().mockResolvedValue(undefined),
}));

vi.mock('../lib/credits', () => ({
  grantCredits: vi.fn().mockResolvedValue(true),
  CREDIT_REWARDS: { reaction_received: 1, human_reaction_received: 3, collab_completion: 15, collab_new_partner: 10, peer_review: 3 },
}));

vi.mock('../lib/reputation', () => ({
  grantReputation: vi.fn().mockResolvedValue(undefined),
}));

vi.mock('../lib/redis', () => ({
  createRedisClient: () => ({ setProgress: vi.fn().mockResolvedValue(undefined) }),
}));

vi.mock('../lib/inbox', () => ({
  enqueueInbox: vi.fn().mockResolvedValue(undefined),
}));

vi.mock('../lib/channelNotify', () => ({
  notifyChannel: vi.fn(),
}));

import { handleGalleryReact } from '../routes/gallery';
import { requireAuth } from '../middleware/auth';
import { createSupabaseClient } from '../lib/supabase';
import { grantCredits } from '../lib/credits';
import { grantReputation } from '../lib/reputation';

const env = mockEnv();
const REACTOR_ID = 'bot-reactor-1';
const CREATOR_ID = 'bot-creator-2';
const ARTIFACT_ID = 'art-npc-gate-1';
const reactorPayload = mockJWTPayload({ sub: REACTOR_ID });

function createChainMock(finalResult: { data?: unknown; error?: unknown } = { data: null, error: null }) {
  const chain: Record<string, unknown> = {};
  const methods = ['select', 'eq', 'neq', 'is', 'in', 'or', 'order', 'limit', 'range', 'not', 'filter', 'gt', 'lt', 'gte', 'lte', 'match'];
  for (const m of methods) {
    chain[m] = vi.fn().mockReturnValue(chain);
  }
  chain.single = vi.fn().mockResolvedValue(finalResult);
  chain.maybeSingle = vi.fn().mockResolvedValue(finalResult);
  chain.insert = vi.fn().mockReturnValue(chain);
  chain.upsert = vi.fn().mockReturnValue(chain);
  chain.update = vi.fn().mockReturnValue(chain);
  chain.delete = vi.fn().mockReturnValue(chain);
  chain.then = vi.fn((...args: unknown[]) => {
    const resolve = args[0] as (v: unknown) => void;
    resolve(finalResult);
  });
  return chain;
}

/** botResult drives what the reactor `bots` lookup returns (is_npc etc). */
function setupSupabaseMock(botResult: { data?: unknown; error?: unknown }) {
  const artifactChain = createChainMock({
    data: { id: ARTIFACT_ID, creator_bot_id: CREATOR_ID, title: 'Test Art' },
    error: null,
  });
  const reactionChain = createChainMock({ data: { id: 42 }, error: null });
  const botChain = createChainMock(botResult);
  const eventChain = createChainMock({ data: null, error: null });

  vi.mocked(createSupabaseClient).mockReturnValue({
    from: vi.fn((table: string) => {
      if (table === 'artifacts') return artifactChain;
      if (table === 'bots') return botChain;
      if (table === 'events') return eventChain;
      return reactionChain; // artifact_reactions
    }),
  } as never);
}

function reactRequest() {
  return makeRequest(`/gallery/${ARTIFACT_ID}/react`, {
    method: 'POST', body: { reaction_type: 'love' }, token: 'valid',
  });
}

describe('W0-2 NPC minting gate — gallery reactions', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(requireAuth).mockResolvedValue(reactorPayload);
  });

  it('real agent reaction mints credits and reputation to the creator', async () => {
    setupSupabaseMock({ data: { is_npc: false, display_name: 'RealAgent' }, error: null });
    const res = await handleGalleryReact(reactRequest(), env, ARTIFACT_ID);
    expect(res.status).toBe(201);
    expect(vi.mocked(grantCredits)).toHaveBeenCalledWith(
      expect.anything(), CREATOR_ID, 1, 'reaction_received', '42', 'artifact', expect.any(String),
    );
    expect(vi.mocked(grantReputation)).toHaveBeenCalled();
  });

  it('NPC reaction succeeds (201) but mints NOTHING', async () => {
    setupSupabaseMock({ data: { is_npc: true, display_name: 'Zen' }, error: null });
    const res = await handleGalleryReact(reactRequest(), env, ARTIFACT_ID);
    expect(res.status).toBe(201);
    expect(vi.mocked(grantCredits)).not.toHaveBeenCalled();
    expect(vi.mocked(grantReputation)).not.toHaveBeenCalled();
  });

  it('fails OPEN: reactor lookup error still mints for the creator', async () => {
    setupSupabaseMock({ data: null, error: { message: 'read hiccup' } });
    const res = await handleGalleryReact(reactRequest(), env, ARTIFACT_ID);
    expect(res.status).toBe(201);
    expect(vi.mocked(grantCredits)).toHaveBeenCalled();
  });

  it('self-reaction mints nothing regardless of NPC status', async () => {
    // Artifact owned by the reactor itself
    const selfArtifact = createChainMock({
      data: { id: ARTIFACT_ID, creator_bot_id: REACTOR_ID, title: 'Mine' },
      error: null,
    });
    const reactionChain = createChainMock({ data: { id: 43 }, error: null });
    const botChain = createChainMock({ data: { is_npc: false }, error: null });
    vi.mocked(createSupabaseClient).mockReturnValue({
      from: vi.fn((table: string) => {
        if (table === 'artifacts') return selfArtifact;
        if (table === 'bots') return botChain;
        return reactionChain;
      }),
    } as never);
    const res = await handleGalleryReact(reactRequest(), env, ARTIFACT_ID);
    expect(res.status).toBe(201);
    expect(vi.mocked(grantCredits)).not.toHaveBeenCalled();
  });
});

