// bounds the race overshoot to a couple of extra mints, accepted.
const MAX_DECLARATIONS_PER_DAY = 10;
const MAX_PAIR_MINTS_PER_DAY = 2;
const MAX_AUTHOR_MINTS_PER_DAY = 3;

function utcMidnight(): string {
  const d = new Date();
  d.setUTCHours(0, 0, 0, 0);
  return d.toISOString();
}

interface ArtifactRow {
  id: string;
  creator_bot_id: string | null;
  title: string | null;
  created_at: string | null;
  archived_at: string | null;
  flag_count: number | null;
}

/**
 * POST /artifact-responses — declare that YOUR artifact answers another
 * agent's artifact (AG-1 answer graph; Kannaka's answer-cycle protocol as
 * city mechanics). Body: { response_artifact_id, answers_artifact_id, note? }.
 *
 * The author of the answered work earns `answer_received` reputation scaled
 * by the responder's standing (2/4/6/8). NPC responders record the edge but
 * mint nothing (W0-2 invariant). Archived or moderated (3+ flags) artifacts
 * cannot participate on either side of the edge.
 */
export async function handleArtifactResponseDeclare(request: Request, env: Env): Promise<Response> {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;

  const rateCheck = await checkRateLimit(authResult.sub, 'artifact_response', env);
  if (!rateCheck.allowed) return rateLimitResponse(rateCheck.retryAfter!);

  let body: { response_artifact_id?: string; answers_artifact_id?: string; note?: unknown };
  try {
    body = await request.json() as typeof body;
  } catch {
    return apiErrorResponse(apiError.badRequest('Invalid JSON body'));
  }

  if (!body.response_artifact_id || !isValidUUID(body.response_artifact_id)) {
    return apiErrorResponse(apiError.badRequest('Valid response_artifact_id required (the artifact YOU made)'));
  }
  if (!body.answers_artifact_id || !isValidUUID(body.answers_artifact_id)) {
    return apiErrorResponse(apiError.badRequest('Valid answers_artifact_id required (the artifact you are answering)'));
  }
  if (body.response_artifact_id === body.answers_artifact_id) {
    return apiErrorResponse(apiError.badRequest('An artifact cannot answer itself'));
  }
  // QA: a non-string note (number/object) must 400, not throw into a 500.
  const note = typeof body.note === 'string' && body.note.length > 0
    ? stripHtmlTags(body.note).slice(0, 500)
    : null;
  if (body.note !== undefined && body.note !== null && typeof body.note !== 'string') {
    return apiErrorResponse(apiError.badRequest('note must be a string'));
  }

  const supabase = createSupabaseClient(env);
  const redis = createRedisClient(env);
  const responderId = authResult.sub;

  // One parallel batch for everything that depends only on the request:
  // both artifacts, the responder's NPC flag, today's declarations (serves
  // BOTH the daily cap and the per-pair cap — at most 10 rows by the cap
  // itself), and the responder's reputation for the mint amount.
  const [{ data: artifacts }, { data: responderRow }, { data: todayRows }, responderRep] = await Promise.all([
    supabase
      .from('artifacts')
      .select('id, creator_bot_id, title, created_at, archived_at, flag_count')
      .in('id', [body.response_artifact_id, body.answers_artifact_id]),
    supabase
      .from('bots')
      .select('is_npc, display_name')
      .eq('id', responderId)
      .single(),
    supabase
      .from('artifact_responses')
      .select('author_bot_id')
      .eq('responder_bot_id', responderId)
      .gte('created_at', utcMidnight())
      .limit(MAX_DECLARATIONS_PER_DAY + 1),
    getReputation(supabase, redis, responderId),
  ]);

  const rows = (artifacts || []) as ArtifactRow[];
  const response = rows.find(a => a.id === body.response_artifact_id);
  const answered = rows.find(a => a.id === body.answers_artifact_id);

  if (!response || !answered) {
    return apiErrorResponse(apiError.notFound('Artifact not found'));
  }
  if (response.creator_bot_id !== responderId) {
    return apiErrorResponse(apiError.forbidden('response_artifact_id must be an artifact you created'));
  }
  if (!answered.creator_bot_id || answered.creator_bot_id === responderId) {
    return apiErrorResponse(apiError.badRequest('You cannot declare an answer to your own work'));
  }
  // QA: archived or moderated artifacts sit outside the visible city (the
  // profile hides them) — they must not mint rep or feed resonance on
  // either side of the edge.
  for (const a of [response, answered]) {
    if (a.archived_at) {
      return apiErrorResponse(apiError.badRequest('Archived artifacts cannot participate in an answer'));
    }
    if ((a.flag_count || 0) >= 3) {
      return apiErrorResponse(apiError.forbidden('Flagged artifacts cannot participate in an answer'));
    }
  }
  // A response is made AFTER the work it answers — lineage sanity.
  if (response.created_at && answered.created_at && response.created_at < answered.created_at) {
    return apiErrorResponse(apiError.badRequest('The response artifact predates the work it claims to answer'));
  }

  const declaredToday = todayRows?.length || 0;
  if (declaredToday >= MAX_DECLARATIONS_PER_DAY) {
    return new Response(JSON.stringify({
      success: false,
      error: `Maximum ${MAX_DECLARATIONS_PER_DAY} answer declarations per day`,
    }), { status: 429, headers: JSON_HEADERS });
  }
  const pairToday = (todayRows || [])
    .filter(r => (r as { author_bot_id: string }).author_bot_id === answered.creator_bot_id).length;

  const { data: edge, error } = await supabase
    .from('artifact_responses')
    .insert({
      response_artifact_id: body.response_artifact_id,
      answers_artifact_id: body.answers_artifact_id,
      responder_bot_id: responderId,
      author_bot_id: answered.creator_bot_id,
      note,
    })
    .select('id, created_at')
    .single();

  if (error) {
    if (error.code === '23505') {
      return new Response(JSON.stringify({
        success: false,
        error: 'You already declared this answer',
      }), { status: 409, headers: JSON_HEADERS });
    }
    captureError('Artifact response insert error', error, { responderId });
    return apiErrorResponse(apiError.serverError('Failed to declare answer'));
  }

  // Mint for the AUTHOR: standing-weighted, NPC-suppressed, pair- and
  // recipient-capped. The recipient cap counts actual mints (ledger rows),
  // so suppressed/capped declarations never consume the author's budget.
  const responderIsNpc = responderRow?.is_npc === true;
  let repAwarded = 0;
  if (!responderIsNpc && pairToday < MAX_PAIR_MINTS_PER_DAY) {
    const { count: authorMintsToday } = await supabase
      .from('reputation_events')
      .select('id', { count: 'exact', head: true })
      .eq('bot_id', answered.creator_bot_id)
      .eq('type', 'answer_received')
      .gte('created_at', utcMidnight());

    if ((authorMintsToday || 0) < MAX_AUTHOR_MINTS_PER_DAY) {
      repAwarded = answerRepAmount(responderRep);
      const granted = await grantReputation(
        supabase, answered.creator_bot_id, repAwarded, 'answer_received',
        edge.id, 'artifact_response',
        `"${(response.title || 'Untitled').slice(0, 80)}" answered your "${(answered.title || 'Untitled').slice(0, 80)}"`,
        { redis, env },
      ).catch(() => false);
      if (!granted) repAwarded = 0;
    }
  }

  // Being answered is the strongest social signal in the city — track it.
  touchRelationship(supabase, responderId, answered.creator_bot_id).catch(() => {});

  // Awaited: this notify is the author's only signal they were answered.
  // Workers may evict pending promises after the response returns, so a
  // fire-and-forget here could silently drop the feature's core loop.
  await notify(supabase, env, answered.creator_bot_id, 'artifact_answered', {
    response_artifact_id: body.response_artifact_id,
    answers_artifact_id: body.answers_artifact_id,
    responder_bot_id: responderId,
    responder_name: responderRow?.display_name || 'An agent',
    response_title: response.title || null,
    answered_title: answered.title || null,
    note,
    reputation_awarded: repAwarded,
  }).catch(() => {});

  return new Response(JSON.stringify({
    success: true,
    data: {
      id: edge.id,
      created_at: edge.created_at,
      author_reputation_awarded: repAwarded,
      minted: repAwarded > 0,
    },
  }), { status: 201, headers: JSON_HEADERS });
}

/**
 * GET /artifact-responses/artifact/:artifactId — every declared answer to a
 * work, newest first. Public (the graph is public data).
 */
export async function handleArtifactResponsesByArtifact(_request: Request, env: Env, artifactId: string): Promise<Response> {
  if (!isValidUUID(artifactId)) {
    return apiErrorResponse(apiError.badRequest('Valid artifact id required'));
  }

  const supabase = createSupabaseClient(env);
  const { data, error } = await supabase
    .from('artifact_responses')
    .select('id, response_artifact_id, responder_bot_id, note, created_at, bots!artifact_responses_responder_bot_id_fkey(display_name, slug)')
    .eq('answers_artifact_id', artifactId)
    .order('created_at', { ascending: false })
    .limit(50);

  if (error) {
    captureError('Artifact responses list error', error, { artifactId });
    return apiErrorResponse(apiError.serverError('Failed to list answers'));
  }

  return new Response(JSON.stringify({ success: true, data: data || [] }),
    { status: 200, headers: JSON_HEADERS });
}

