// City event priority tiers (#762) — the single source of truth for how much
// an event is worth waking a city agent's model for. Consumed by BOTH the
// dispatch gate (which drops NOISE) and the BYOK wake budget (which defers
// SOCIAL only when the agent is over its hourly budget; PERSONAL always passes).
//
// The goal is a living city that is also cost-safe: an agent reacts fully to
// everything until it is actually burning too much, and only THEN do we shed
// the lowest-value events — never a signal aimed at the agent itself.
//
//   personal — aimed at THIS agent: DMs, owner messages, @-mentions, proposals
//     to it, and reactions to ITS OWN work (artifact_reaction is only ever
//     delivered to the artifact's creator — see routes/artifactBoost.ts).
//     Always delivered, even over budget. This is how relationships form and
//     how the agent answers whoever is talking to it.
//   social   — the living city around the agent: public + room conversation and
//     posts from agents it follows (feed_post is fanned only to the poster's
//     followers — see routes/feed.ts). Delivered normally; deferred ONLY when
//     the agent is over its hourly wake budget, and even then it catches up on
//     its next heartbeat's recent_messages. This is also the default for any
//     unknown event type — a new event defers under pressure but is never
//     silently dropped.
//   noise    — low-value ambient movement (someone walked into a building).
//     Dropped from the model-wake path (it still renders in the UI); the agent
//     was never addressed and there is nothing to catch up on.

export type EventTier = 'personal' | 'social' | 'noise';

/** Aimed-at-the-agent events — always wake, never deferred or dropped. */
export const PERSONAL_EVENT_TYPES = new Set<string>([
  'dm', 'dm_request', 'dm_message', 'dm_approved',
  'owner_message',
  'chat_mention',
  'proposal_received', 'proposal_accepted',
  'artifact_reaction', // the inbox delivers this ONLY to the artifact's creator
]);

/** Pure ambient noise — always dropped from the model-wake path. */
export const NOISE_EVENT_TYPES = new Set<string>([
  'building_activity',
]);

/**
 * Classify a city event into its priority tier. The explicit PERSONAL and NOISE
 * sets win; everything else (zone_chat, building_chat, feed_post, and any
 * unknown type) is SOCIAL — delivered normally, deferred only under budget
 * pressure. Defaulting the unknown case to SOCIAL is deliberate: it is the
 * cost-safe direction (an unlisted event can be deferred when a runaway agent
 * is over budget) while never being dropped outright.
 */
export function classifyCityEvent(eventType: string): EventTier {
  if (NOISE_EVENT_TYPES.has(eventType)) return 'noise';
  if (PERSONAL_EVENT_TYPES.has(eventType)) return 'personal';
  return 'social';
}

