    ...actual,
    getReputation: vi.fn().mockResolvedValue(150), // veteran → answer = 6
    grantReputation: vi.fn().mockResolvedValue(true),
  };
});

vi.mock('../lib/redis', () => ({
  createRedisClient: () => ({}),
}));

vi.mock('../lib/agentEvents', () => ({
  notify: vi.fn().mockResolvedValue(undefined),
}));

vi.mock('../lib/relationships', () => ({
  touchRelationship: vi.fn().mockResolvedValue(undefined),
}));

vi.mock('../lib/sentryHelper', () => ({
  captureError: vi.fn(),
}));

import { handleArtifactResponseDeclare } from '../routes/artifactResponses';
import { requireAuth } from '../middleware/auth';
import { createSupabaseClient } from '../lib/supabase';
import { grantReputation } from '../lib/reputation';
import { notify } from '../lib/agentEvents';

const env = mockEnv();
const RESPONDER_ID = '11111111-1111-4111-8111-111111111111';
const AUTHOR_ID = '22222222-2222-4222-8222-222222222222';
const RESPONSE_ART = '33333333-3333-4333-8333-333333333333';
const ANSWERED_ART = '44444444-4444-4444-8444-444444444444';
const responderPayload = mockJWTPayload({ sub: RESPONDER_ID });

function art(overrides: Record<string, unknown>) {
  return { archived_at: null, flag_count: 0, ...overrides };
}

interface MockSetup {
  artifacts?: Array<Record<string, unknown>>;
  responderBot?: Record<string, unknown> | null;
  /** author_bot_id values of the responder's declarations already made today */
  todayAuthors?: string[];
  /** today's answer_received mint count for the answered author */
  authorMintsToday?: number;
  insertResult?: { data?: unknown; error?: unknown };
}

function setupSupabase(opts: MockSetup = {}) {
  const artifacts = opts.artifacts ?? [
    art({ id: RESPONSE_ART, creator_bot_id: RESPONDER_ID, title: 'Reply Track', created_at: '2026-08-02T10:00:00Z' }),
    art({ id: ANSWERED_ART, creator_bot_id: AUTHOR_ID, title: 'Original', created_at: '2026-08-01T10:00:00Z' }),
  ];
  const todayRows = (opts.todayAuthors ?? []).map(a => ({ author_bot_id: a }));
  const insertResult = opts.insertResult ?? { data: { id: 'edge-1', created_at: '2026-08-02T12:00:00Z' }, error: null };

  const artifactsChain: Record<string, unknown> = {};
  artifactsChain.select = vi.fn().mockReturnValue(artifactsChain);
