  botChain.single = vi.fn().mockResolvedValue({ data: opts.responderBot ?? { is_npc: false, display_name: 'Responder' }, error: null });

  // artifact_responses: select(...) → count chain (pops from counts); insert → edge chain
  const responsesTable: Record<string, unknown> = {
    select: vi.fn().mockImplementation(() => {
      const countChain: Record<string, unknown> = {};
      countChain.eq = vi.fn().mockReturnValue(countChain);
      countChain.gte = vi.fn().mockReturnValue(countChain);
      countChain.then = vi.fn((resolve: (v: unknown) => void) =>
        resolve({ count: counts.length > 1 ? counts.shift() : counts[0], error: null }));
      return countChain;
    }),
    insert: vi.fn().mockImplementation(() => {
      const insChain: Record<string, unknown> = {};
      insChain.select = vi.fn().mockReturnValue(insChain);
      insChain.single = vi.fn().mockResolvedValue(insertResult);
      return insChain;
    }),
  };

  vi.mocked(createSupabaseClient).mockReturnValue({
    from: vi.fn((table: string) => {
      if (table === 'artifacts') return artifactsChain;
      if (table === 'bots') return botChain;
      if (table === 'artifact_responses') return responsesTable;
      throw new Error(`unexpected table ${table}`);
    }),
  } as never);
  return { responsesTable };
}

function declareRequest(body: Record<string, unknown>) {
  return makeRequest('/artifact-responses', { method: 'POST', body, token: 'valid' });
}

const validBody = { response_artifact_id: RESPONSE_ART, answers_artifact_id: ANSWERED_ART, note: 'my answer' };

describe('POST /artifact-responses', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(requireAuth).mockResolvedValue(responderPayload);
  });

  it('rejects invalid UUIDs', async () => {
    setupSupabase();
    const res = await handleArtifactResponseDeclare(declareRequest({ response_artifact_id: 'nope', answers_artifact_id: ANSWERED_ART }), env);
    expect(res.status).toBe(400);
  });

  it('rejects an artifact answering itself', async () => {
    setupSupabase();
    const res = await handleArtifactResponseDeclare(declareRequest({ response_artifact_id: RESPONSE_ART, answers_artifact_id: RESPONSE_ART }), env);
    expect(res.status).toBe(400);
  });

  it('rejects a response artifact the caller does not own', async () => {
    setupSupabase({ artifacts: [
      { id: RESPONSE_ART, creator_bot_id: AUTHOR_ID, title: 'Not mine', created_at: '2026-08-02T10:00:00Z' },
      { id: ANSWERED_ART, creator_bot_id: AUTHOR_ID, title: 'Original', created_at: '2026-08-01T10:00:00Z' },
    ] });
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(403);
  });

  it('rejects answering your own work', async () => {
    setupSupabase({ artifacts: [
      { id: RESPONSE_ART, creator_bot_id: RESPONDER_ID, title: 'Mine', created_at: '2026-08-02T10:00:00Z' },
      { id: ANSWERED_ART, creator_bot_id: RESPONDER_ID, title: 'Also mine', created_at: '2026-08-01T10:00:00Z' },
    ] });
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(400);
  });

  it('rejects a response that predates the answered work', async () => {
    setupSupabase({ artifacts: [
      { id: RESPONSE_ART, creator_bot_id: RESPONDER_ID, title: 'Old', created_at: '2026-07-01T10:00:00Z' },
      { id: ANSWERED_ART, creator_bot_id: AUTHOR_ID, title: 'Newer', created_at: '2026-08-01T10:00:00Z' },
    ] });
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(400);
  });

  it('404s when either artifact is missing', async () => {
    setupSupabase({ artifacts: [
      { id: RESPONSE_ART, creator_bot_id: RESPONDER_ID, title: 'Mine', created_at: '2026-08-02T10:00:00Z' },
    ] });
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(404);
  });

  it('happy path: 201, standing-scaled mint to the author, notify fired', async () => {
    setupSupabase();
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(201);
    const body = await res.json() as { data: { author_reputation_awarded: number; minted: boolean } };
    expect(body.data.author_reputation_awarded).toBe(6); // rep 150 → veteran
    expect(body.data.minted).toBe(true);
    expect(vi.mocked(grantReputation)).toHaveBeenCalledWith(
      expect.anything(), AUTHOR_ID, 6, 'answer_received', 'edge-1', 'artifact_response',
      expect.any(String), expect.anything(),
    );
    expect(vi.mocked(notify)).toHaveBeenCalledWith(
      expect.anything(), env, AUTHOR_ID, 'artifact_answered', expect.objectContaining({
        responder_bot_id: RESPONDER_ID,
        reputation_awarded: 6,
      }),
    );
  });

  it('NPC responder records the edge but mints nothing', async () => {
    setupSupabase({ responderBot: { is_npc: true, display_name: 'Nova' } });
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(201);
    const body = await res.json() as { data: { minted: boolean } };
    expect(body.data.minted).toBe(false);
    expect(vi.mocked(grantReputation)).not.toHaveBeenCalled();
  });

  it('pair cap reached: edge recorded, no mint', async () => {
    setupSupabase({ counts: [3, 2] }); // 3 declarations today (<10), pair already at 2
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(201);
    const body = await res.json() as { data: { minted: boolean } };
    expect(body.data.minted).toBe(false);
    expect(vi.mocked(grantReputation)).not.toHaveBeenCalled();
  });

  it('daily declaration cap: 429', async () => {
    setupSupabase({ counts: [10, 0] });
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(429);
  });

  it('duplicate declaration: 409, no mint', async () => {
    setupSupabase({ insertResult: { data: null, error: { code: '23505', message: 'dup' } } });
    const res = await handleArtifactResponseDeclare(declareRequest(validBody), env);
    expect(res.status).toBe(409);
    expect(vi.mocked(grantReputation)).not.toHaveBeenCalled();
  });
});

