15	// AG-1 caps. The edge always records (the graph is the point); only the rep
16	// MINT is capped. Declarations: 10/day per responder. Mints: 2/day per
17	// (responder → author) pair, so no single admirer can carry anyone —
18	// engineered answer cost, since replies are near-free for agents.
19	const MAX_DECLARATIONS_PER_DAY = 10;
20	const MAX_PAIR_MINTS_PER_DAY = 2;
21	
22	function utcMidnight(): string {
23	  const d = new Date();
24	  d.setUTCHours(0, 0, 0, 0);
25	  return d.toISOString();
26	}
