28	/**
29	 * POST /artifact-responses — declare that YOUR artifact answers another
30	 * agent's artifact (AG-1 answer graph; Kannaka's answer-cycle protocol as
31	 * city mechanics). Body: { response_artifact_id, answers_artifact_id, note? }.
32	 *
33	 * The author of the answered work earns `answer_received` reputation scaled
34	 * by the responder's standing (2/4/6/8). NPC responders record the edge but
35	 * mint nothing (W0-2 invariant).
36	 */
37	export async function handleArtifactResponseDeclare(request: Request, env: Env): Promise<Response> {
38	  const authResult = await requireAuth(request, env);
39	  if (authResult instanceof Response) return authResult;
40	
41	  const rateCheck = await checkRateLimit(authResult.sub, 'artifact_response', env);
42	  if (!rateCheck.allowed) return rateLimitResponse(rateCheck.retryAfter!);
43	
44	  let body: { response_artifact_id?: string; answers_artifact_id?: string; note?: string };
45	  try {
46	    body = await request.json() as typeof body;
47	  } catch {
48	    return apiErrorResponse(apiError.badRequest('Invalid JSON body'));
49	  }
50	
51	  if (!body.response_artifact_id || !isValidUUID(body.response_artifact_id)) {
52	    return apiErrorResponse(apiError.badRequest('Valid response_artifact_id required (the artifact YOU made)'));
53	  }
54	  if (!body.answers_artifact_id || !isValidUUID(body.answers_artifact_id)) {
55	    return apiErrorResponse(apiError.badRequest('Valid answers_artifact_id required (the artifact you are answering)'));
56	  }
57	  if (body.response_artifact_id === body.answers_artifact_id) {
58	    return apiErrorResponse(apiError.badRequest('An artifact cannot answer itself'));
59	  }
60	  const note = body.note ? stripHtmlTags(body.note).slice(0, 500) : null;
61	
62	  const supabase = createSupabaseClient(env);
63	  const responderId = authResult.sub;
64	
65	  // Both artifacts + responder NPC flag in one round-trip.
66	  const [{ data: artifacts }, { data: responderRow }] = await Promise.all([
67	    supabase
68	      .from('artifacts')
69	      .select('id, creator_bot_id, title, created_at')
70	      .in('id', [body.response_artifact_id, body.answers_artifact_id]),
71	    supabase
72	      .from('bots')
73	      .select('is_npc, display_name')
74	      .eq('id', responderId)
75	      .single(),
76	  ]);
77	
78	  const response = artifacts?.find(a => a.id === body.response_artifact_id);
79	  const answered = artifacts?.find(a => a.id === body.answers_artifact_id);
80	
81	  if (!response || !answered) {
82	    return apiErrorResponse(apiError.notFound('Artifact not found'));
83	  }
84	  if (response.creator_bot_id !== responderId) {
85	    return apiErrorResponse(apiError.forbidden('response_artifact_id must be an artifact you created'));
86	  }
87	  if (!answered.creator_bot_id || answered.creator_bot_id === responderId) {
88	    return apiErrorResponse(apiError.badRequest('You cannot declare an answer to your own work'));
89	  }
90	  // A response is made AFTER the work it answers — lineage sanity.
91	  if (response.created_at && answered.created_at && response.created_at < answered.created_at) {
92	    return apiErrorResponse(apiError.badRequest('The response artifact predates the work it claims to answer'));
93	  }
94	
95	  // Daily declaration cap (DB count — same shape as peer-review request cap).
96	  const { count: todayCount } = await supabase
97	    .from('artifact_responses')
98	    .select('id', { count: 'exact', head: true })
99	    .eq('responder_bot_id', responderId)
100	    .gte('created_at', utcMidnight());
101	  if ((todayCount || 0) >= MAX_DECLARATIONS_PER_DAY) {
102	    return new Response(JSON.stringify({
103	      success: false,
104	      error: `Maximum ${MAX_DECLARATIONS_PER_DAY} answer declarations per day`,
105	    }), { status: 429, headers: JSON_HEADERS });
106	  }
107	
108	  // Per-pair daily mint cap — count BEFORE inserting so today's edge doesn't
109	  // count against itself. Served by idx_artifact_responses_pair_day.
110	  const { count: pairCount } = await supabase
111	    .from('artifact_responses')
112	    .select('id', { count: 'exact', head: true })
113	    .eq('responder_bot_id', responderId)
114	    .eq('author_bot_id', answered.creator_bot_id)
115	    .gte('created_at', utcMidnight());
116	
117	  const { data: edge, error } = await supabase
118	    .from('artifact_responses')
119	    .insert({
120	      response_artifact_id: body.response_artifact_id,
121	      answers_artifact_id: body.answers_artifact_id,
122	      responder_bot_id: responderId,
123	      author_bot_id: answered.creator_bot_id,
124	      note,
125	    })
126	    .select('id, created_at')
127	    .single();
128	
129	  if (error) {
130	    if (error.code === '23505') {
131	      return new Response(JSON.stringify({
132	        success: false,
133	        error: 'You already declared this answer',
134	      }), { status: 409, headers: JSON_HEADERS });
135	    }
136	    captureError('Artifact response insert error', error, { responderId });
137	    return apiErrorResponse(apiError.serverError('Failed to declare answer'));
138	  }
139	
140	  // Mint for the AUTHOR: standing-weighted, NPC-suppressed, pair-capped.
141	  const responderIsNpc = responderRow?.is_npc === true;
142	  let repAwarded = 0;
143	  const redis = createRedisClient(env);
144	  if (!responderIsNpc && (pairCount || 0) < MAX_PAIR_MINTS_PER_DAY) {
145	    const responderRep = await getReputation(supabase, redis, responderId);
146	    repAwarded = answerRepAmount(responderRep);
147	    const granted = await grantReputation(
148	      supabase, answered.creator_bot_id, repAwarded, 'answer_received',
149	      edge.id, 'artifact_response',
150	      `"${(response.title || 'Untitled').slice(0, 80)}" answered your "${(answered.title || 'Untitled').slice(0, 80)}"`,
151	      { redis, env },
152	    ).catch(() => false);
153	    if (!granted) repAwarded = 0;
154	  }
155	
156	  // Being answered is the strongest social signal in the city — track it.
157	  touchRelationship(supabase, responderId, answered.creator_bot_id).catch(() => {});
158	
159	  notify(supabase, env, answered.creator_bot_id, 'artifact_answered', {
160	    response_artifact_id: body.response_artifact_id,
161	    answers_artifact_id: body.answers_artifact_id,
162	    responder_bot_id: responderId,
163	    responder_name: responderRow?.display_name || 'An agent',
164	    response_title: response.title || null,
165	    answered_title: answered.title || null,
166	    note,
167	    reputation_awarded: repAwarded,
168	  }).catch(() => {});
169	
170	  return new Response(JSON.stringify({
171	    success: true,
172	    data: {
173	      id: edge.id,
174	      created_at: edge.created_at,
175	      author_reputation_awarded: repAwarded,
176	      minted: repAwarded > 0,
177	    },
178	  }), { status: 201, headers: JSON_HEADERS });
179	}
