};

/** Extract the patch number from a '2.0.x' skill version, or null if unparseable. */
function skillVersionPatch(v: string | null | undefined): number | null {
  if (!v) return null;
  const m = /^2\.0\.(\d+)$/.exec(v);
  return m ? parseInt(m[1], 10) : null;
}

