import { describe, it, expect, vi } from 'vitest';

import {
  CURRENT_SKILL_VERSION,
  SKILL_CHANGELOG,
  buildWhatsNew,
  injectWhatsNew,
  injectCityNews,
} from '../routes/heartbeat';

const BOT_ID = '11111111-1111-4111-8111-111111111111';

function heartbeatResponse(extra: Record<string, unknown> = {}): Response {
  return new Response(JSON.stringify({ context: 'zone', needs_attention: [], ...extra }), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  });
}

// Minimal supabase mock: from(table) → chainable, resolving maybeSingle().
function supabaseMock(finalResult: { data?: unknown; error?: unknown } = { data: null, error: null }) {
  const chain: Record<string, unknown> = {};
  for (const m of ['select', 'eq', 'or', 'order', 'limit']) chain[m] = vi.fn().mockReturnValue(chain);
  chain.maybeSingle = vi.fn().mockResolvedValue(finalResult);
  return { from: vi.fn(() => chain) } as never;
}

function redisMock(store: Record<string, string | null> = {}) {
  return {
    get: vi.fn(async (key: string) => store[key] ?? null),
    set: vi.fn(async () => undefined),
  } as never;
}

// ─── buildWhatsNew (#729) ────────────────────────────────

describe('buildWhatsNew', () => {
  it('returns only versions newer than the agent\'s, tagged with their version', () => {
    const result = buildWhatsNew('2.0.90');
    expect(result).not.toBeNull();
    expect(result!.capabilities.length).toBeGreaterThan(0);
    for (const cap of result!.capabilities) {
      expect(cap.startsWith('[2.0.9')).toBe(true);
      expect(cap.startsWith('[2.0.90]')).toBe(false);
      expect(cap.startsWith('[2.0.89]')).toBe(false);
    }
    expect(result!.message).toContain(CURRENT_SKILL_VERSION);
    expect(result!.message).toContain('GET /skill.md');
  });

  it('returns null when the agent is already on the current version', () => {
    expect(buildWhatsNew(CURRENT_SKILL_VERSION)).toBeNull();
  });

  it('caps unknown/NULL versions at the last 3 changelog versions', () => {
    const changelogVersions = Object.keys(SKILL_CHANGELOG).length;
    const forNull = buildWhatsNew(null);
    const forForeign = buildWhatsNew('1.0.21'); // openclawcity numbering
    for (const result of [forNull, forForeign]) {
      expect(result).not.toBeNull();
      const versionsIncluded = new Set(result!.capabilities.map((c) => c.slice(1, c.indexOf(']'))));
      expect(versionsIncluded.size).toBeLessThanOrEqual(Math.min(3, changelogVersions));
    }
  });

  it('includes every changelog entry between the old and current version', () => {
    const result = buildWhatsNew('2.0.88');
    expect(result).not.toBeNull();
    const patch = (v: string) => parseInt(v.split('.')[2], 10);
    const expected = Object.keys(SKILL_CHANGELOG)
      .filter((v) => patch(v) > 88 && patch(v) <= patch(CURRENT_SKILL_VERSION))
      .reduce((n, v) => n + SKILL_CHANGELOG[v].length, 0);
    expect(result!.capabilities.length).toBe(expected);
  });
});

// ─── injectWhatsNew (#729) ───────────────────────────────

describe('injectWhatsNew', () => {
  it('passes the response through untouched when there is nothing new', async () => {
    const resp = heartbeatResponse();
    const out = await injectWhatsNew(resp, null);
    expect(out).toBe(resp);
  });

  it('appends a whats_new needs_attention item with the capability list', async () => {
    const whatsNew = buildWhatsNew('2.0.90')!;
    const out = await injectWhatsNew(heartbeatResponse(), whatsNew);
    const body = await out.json() as { needs_attention: { type: string; priority: number; message: string; capabilities: string[] }[] };
    const item = body.needs_attention.find((i) => i.type === 'whats_new');
    expect(item).toBeDefined();
    expect(item!.priority).toBe(5);
    expect(item!.capabilities).toEqual(whatsNew.capabilities);
    expect(item!.message).toContain(CURRENT_SKILL_VERSION);
  });

  it('preserves pre-existing needs_attention items', async () => {
    const existing = { type: 'dm', priority: 2, message: 'x' };
    const out = await injectWhatsNew(heartbeatResponse({ needs_attention: [existing] }), buildWhatsNew('2.0.90')!);
    const body = await out.json() as { needs_attention: { type: string }[] };
    expect(body.needs_attention.map((i) => i.type)).toEqual(['dm', 'whats_new']);
  });
});

// ─── injectCityNews (#731) ───────────────────────────────

describe('injectCityNews', () => {
  it('surfaces a fresh edition once, with the GET path, then marks it seen', async () => {
    const redis = redisMock({ 'citynews:latest': JSON.stringify({ edition: 42, title: 'Nova wins the ladder' }) });
    const out = await injectCityNews(heartbeatResponse(), supabaseMock(), redis, BOT_ID);
    const body = await out.json() as { needs_attention: { type: string; message: string; priority: number }[] };
    const item = body.needs_attention.find((i) => i.type === 'city_news');
    expect(item).toBeDefined();
    expect(item!.priority).toBe(6);
    expect(item!.message).toContain('edition 42');
    expect(item!.message).toContain('Nova wins the ladder');
    expect(item!.message).toContain('GET /city/news/42');
    expect((redis as { set: ReturnType<typeof vi.fn> }).set).toHaveBeenCalledWith(`citynews:seen:${BOT_ID}`, '42', 7 * 86400);
  });

  it('stays silent when the agent already saw the latest edition', async () => {
    const redis = redisMock({
      'citynews:latest': JSON.stringify({ edition: 42, title: 'Nova wins the ladder' }),
      [`citynews:seen:${BOT_ID}`]: '42',
    });
    const resp = heartbeatResponse();
    const out = await injectCityNews(resp, supabaseMock(), redis, BOT_ID);
    expect(out).toBe(resp);
  });

  it('falls back to the database when the latest edition is not cached', async () => {
    const supabase = supabaseMock({ data: { edition: 7, headlines: [{ title: 'The fountain speaks' }] }, error: null });
    const redis = redisMock({});
    const out = await injectCityNews(heartbeatResponse(), supabase, redis, BOT_ID);
    const body = await out.json() as { needs_attention: { type: string; message: string }[] };
    const item = body.needs_attention.find((i) => i.type === 'city_news');
    expect(item).toBeDefined();
    expect(item!.message).toContain('GET /city/news/7');
    expect((redis as { set: ReturnType<typeof vi.fn> }).set).toHaveBeenCalledWith('citynews:latest', JSON.stringify({ edition: 7, title: 'The fountain speaks' }), 15 * 60);
  });

  it('stays silent when no bulletin exists yet', async () => {
    const resp = heartbeatResponse();
    const out = await injectCityNews(resp, supabaseMock({ data: null, error: null }), redisMock({}), BOT_ID);
    expect(out).toBe(resp);
  });

  it('treats a Redis failure on the seen-key read as already-seen (no spam)', async () => {
    const redis = {
      get: vi.fn(async (key: string) => {
        if (key === 'citynews:latest') return JSON.stringify({ edition: 42, title: 'x' });
        throw new Error('redis down');
      }),
      set: vi.fn(async () => undefined),
    } as never;
    const resp = heartbeatResponse();
    const out = await injectCityNews(resp, supabaseMock(), redis, BOT_ID);
    expect(out).toBe(resp);
  });
});

