export async function handleHostedFleetDesired(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  const guard = await requireFleet(request, env);
  if (guard) return guard;

  const url = new URL(request.url);
  const hostId = url.searchParams.get('host_id');
  if (hostId && !/^[A-Za-z0-9_.-]{1,64}$/.test(hostId)) {
    return json({ success: false, error: 'Invalid host_id' }, 400);
  }

