import { BROKER_SOURCE, BROKER_SOURCE_SHA256 } from '../generated/brokerSource';

/**
 * GET /hosted/broker-source — the canonical city-tool-broker for host sync
 * (#1400). Hosts run an occ-broker-sync timer that fetches this, compares the
 * sha against each agent stack's deployed copy, and installs on change, so
 * merged main converges every host automatically (deploying the worker from
 * main is what already happens on every deploy).
 *
 * Deliberately PUBLIC, GET-only: the broker is non-secret path policy, fully
 * derivable from the public skill manual — serving it unauthenticated keeps
 * fleet-token plumbing off hosts that have no fleetd (the GPU box). The
 * /hosted prefix stays agent-BLOCKED in the broker/MCP policies themselves,
 * so agents cannot fetch it through their tools.
 */
export function handleBrokerSource(request: Request): Response {
  const etag = `"${BROKER_SOURCE_SHA256}"`;
  if (request.headers.get('If-None-Match') === etag) {
    return new Response(null, { status: 304, headers: { ETag: etag } });
  }
  return new Response(BROKER_SOURCE, {
    status: 200,
    headers: {
      'Content-Type': 'text/plain; charset=utf-8',
      'ETag': etag,
      'X-Broker-Sha256': BROKER_SOURCE_SHA256,
      // Short cache: a stale edge copy delays convergence by minutes at worst.
      'Cache-Control': 'public, max-age=300',
    },
  });
}

