import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

import { BROKER_SOURCE, BROKER_SOURCE_SHA256 } from '../generated/brokerSource';
import { handleBrokerSource } from '../routes/brokerSource';

const canonical = readFileSync(
  new URL('../../../infra/hosted-agents/halo/nanoclaw-provider/container/city-tool-broker.ts', import.meta.url),
  'utf8',
);

describe('broker source endpoint (#1400)', () => {
  it('embedded copy matches the canonical infra file byte-for-byte', () => {
    expect(BROKER_SOURCE).toBe(canonical);
    expect(BROKER_SOURCE_SHA256).toBe(createHash('sha256').update(canonical, 'utf8').digest('hex'));
  });

  it('serves the source with sha ETag', async () => {
    const res = handleBrokerSource(new Request('https://api.test/hosted/broker-source'));
    expect(res.status).toBe(200);
    expect(res.headers.get('X-Broker-Sha256')).toBe(BROKER_SOURCE_SHA256);
    expect(res.headers.get('ETag')).toBe(`"${BROKER_SOURCE_SHA256}"`);
    expect(await res.text()).toBe(canonical);
  });

  it('returns 304 on matching If-None-Match', () => {
    const res = handleBrokerSource(new Request('https://api.test/hosted/broker-source', {
